## Why This Is Asked
Tests DP setup for segment selection with non-adjacency and reconstruction, a common beginner DP pattern with a twist.

## Key Concepts
- DP over index i and blocks t
- Enforce non-adjacency via s-2 reference
- Prefix sums for O(1) subarray sums
- Reconstruction pointers for endpoints
- Time/space trade-offs; possible optimization to O(nk) time and O(n) space per k

## Code Example
```javascript
function maxKSubarraysSum(A, k) {
  const n = A.length;
  const P = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) P[i + 1] = P[i] + A[i];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const take = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      // skip i
      dp[i][t] = Math.max(dp[i][t], dp[i - 1][t]);
      if (t > 0) {
        for (let s = 1; s <= i; s++) {
          const sum = P[i] - P[s - 1];
          const prev = (s >= 2) ? dp[s - 2][t - 1] : (t - 1 === 0 ? 0 : -Infinity);
          const cand = sum + prev;
          if (cand > dp[i][t]) {
            dp[i][t] = cand;
            take[i][t] = s;
          }
        }
      }
    }
  }
  // reconstruction would trace back using 'take' from (n, bestT)
  return { maxSum: dp[n][0], blocks: [] };
}
```

## Why This Is Asked

Tests a fresh DP angle: interval-based value depends on distinct characters within each substring, plus precise reconstruction for k blocks.

## Key Concepts

- Non-overlapping interval DP
- Precomputing distinct counts for all substrings
- Reconstruction via back-pointers
- Time/space trade-offs and potential optimizations

## Code Example

```javascript
// Implementation sketch
function maxKSubstrings(s, k) {
  const n = s.length;
  const dist = Array.from({length: n}, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    const freq = new Array(26).fill(0);
    let setBits = 0;
    for (let j = i; j >= 0; j--) {
      const idx = s.charCodeAt(j) - 97;
      if (freq[idx]++ === 0) setBits++;
      dist[j][i] = setBits;
    }
  }

  const dp = Array.from({length: n+1}, () => Array(k+1).fill(-Infinity));
  const prev = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  const start = Array.from({length: n+1}, () => Array(k+1).fill(-1));

  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    dp[i][0] = 0;
    for (let t = 1; t <= k; t++) {
      // Option 1: skip i
      if (dp[i-1][t] > dp[i][t]) {
        dp[i][t] = dp[i-1][t];
        prev[i][t] = i-1;
        start[i][t] = start[i-1][t];
      }

      // Option 2: end t-th substring at i
      for (let s = 1; s <= i; s++) {
        const val = dp[s-1][t-1] + dist[s-1][i-1];
        if (val > dp[i][t]) {
          dp[i][t] = val;
          prev[i][t] = s-1;
          start[i][t] = s-1;
        }
      }
    }
  }

  // Reconstruct substrings
  const result = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    if (prev[i][t] === i-1) {
      i--;
    } else {
      result.unshift([start[i][t]+1, i]);
      i = prev[i][t];
      t--;
    }
  }

  return { maxValue: dp[n][k], substrings: result };
}
```

Time complexity: O(n²k) for DP transitions + O(n²) for preprocessing. Space: O(n² + nk). Optimizations include limiting the inner loop or using convex hull tricks for special cases.

## Why This Is Asked
This question tests a harder variant of partition DP where each block's value depends on its range (max-min). It requires careful state design, precomputation of subarray values, and backtracking to output exact k non-overlapping blocks.

## Key Concepts
- 2D DP over prefix index and number of blocks
- Precomputing block values V[l][r] = max - min for all subarrays
- Reconstruction via parent pointers to output endpoints

## Code Example
```javascript
function maxRangeSubarrayValue(A, k) {
  const n = A.length;
  const V = Array.from({ length: n }, () => Array(n).fill(0));
  for (let l = 0; l < n; l++) {
    let mx = -Infinity, mn = Infinity;
    for (let r = l; r < n; r++) {
      mx = Math.max(mx, A[r]);
      mn = Math.min(mn, A[r]);
      V[l][r] = mx - mn;
    }
  }

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const parent = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      for (let j = 1; j <= i; j++) {
        const val = dp[j - 1][t - 1] + V[j - 1][i - 1];
        if (val > dp[i][t]) {
          dp[i][t] = val;
          parent[i][t] = j;
        }
      }
    }
  }

  const blocks = [];
  let i = n, t = k;
  while (t > 0 && parent[i][t] !== -1) {
    const j = parent[i][t];
    blocks.push([j, i]);
    i = j - 1;
    t--;
  }
  return { value: dp[n][k], blocks: blocks.reverse() };
}
```

## Why This Is Asked
Tests real DP design with an extra state (discount used) and careful recurrence.

## Key Concepts
- 2D DP with a binary state (discount used or not)
- Transitions combine taking cost with/without discount
- Space optimization using rolling arrays

## Code Example
```javascript
function minCostWithDiscount(grid){
  const n = grid.length, m = grid[0].length;
  const INF = 1e15;
  let dp0 = new Array(m).fill(INF);
  let dp1 = new Array(m).fill(INF);
  dp0[0] = grid[0][0];
  dp1[0] = Math.floor(grid[0][0] / 2);
  for (let j = 1; j < m; j++) {
    dp0[j] = grid[0][j] + dp0[j-1];
    dp1[j] = Math.min(grid[0][j] + dp1[j-1], Math.floor(grid[0][j]/2) + dp0[j-1]);
  }
  for (let i = 1; i < n; i++) {
    dp0[0] += grid[i][0];
    dp1[0] = Math.min(grid[i][0] + dp1[0], Math.floor(grid[i][0]/2) + dp0[0-1]);
    for (let j = 1; j < m; j++) {
      const v = grid[i][j];
      dp1[j] = Math.min(v + Math.min(dp1[j], dp1[j-1]), Math.floor(v/2) + Math.min(dp0[j], dp0[j-1]));
      dp0[j] = v + Math.min(dp0[j], dp0[j-1]);
    }
  }
  return dp1[m-1];
}
```

